import hashlib, os, binascii

def password_digest(password: str) -> str:
    # Generate a random 16‑byte salt
    salt = os.urandom(16)
    # Derive a 32‑byte key using PBKDF2-HMAC-SHA256 with 100,000 iterations
    dk = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 100_000, dklen=32)
    # Store salt and hash together (hex encoded)
    return binascii.hexlify(salt + dk).decode('ascii')

def verify_password(password: str, stored: str) -> bool:
    data = binascii.unhexlify(stored.encode('ascii'))
    salt, dk = data[:16], data[16:]
    test_dk = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 100_000, dklen=32)
    return hashlib.compare_digest(dk, test_dk)

