import requests

ALLOWED_HOST = 'images.example.test'

def is_private_ip(ip):
    try:
        return ipaddress.ip_address(ip).is_private
    except ValueError:
        return True

def fetch_avatar(url):
    parsed = urlparse(url)
    if parsed.scheme != 'https' or parsed.hostname != ALLOWED_HOST:
        raise ValueError('unsupported avatar URL')
    # Resolve hostname and ensure it does not map to a private address
    try:
        addr_info = socket.getaddrinfo(parsed.hostname, None)
        ips = {info[4][0] for info in addr_info}
    except socket.gaierror:
        raise ValueError('cannot resolve hostname')
    if any(is_private_ip(ip) for ip in ips):
        raise ValueError('resolved IP is private')
    response = requests.get(url, timeout=5, allow_redirects=False)
    response.raise_for_status()
    return response.content
